
:root{--wine:#250005;--red:#65070d;--red2:#8e1118;--gold:#d7a746;--gold2:#f5dc93;--cream:#fff4d2;--muted:#cbb9a1;--black:#100103;--line:rgba(234,190,85,.25)}
*{box-sizing:border-box;margin:0;padding:0}html{scroll-behavior:smooth}body{font-family:"DM Sans",sans-serif;background:var(--wine);color:#fff;overflow-x:hidden}a{text-decoration:none;color:inherit}img{display:block;max-width:100%}.container{width:min(1180px,92%);margin:auto}section{position:relative;overflow:hidden}.section{padding:110px 0}.eyebrow{font-size:11px;letter-spacing:4px;text-transform:uppercase;color:var(--gold2);font-weight:700}h1,h2,h3,.logo{font-family:Cinzel,serif}h2{font-size:clamp(34px,5vw,65px);line-height:1.05;color:var(--cream)}.section-head{text-align:center;max-width:800px;margin:0 auto 55px}.section-head .eyebrow{margin-bottom:15px}.section-head p{color:var(--muted);line-height:1.9;margin-top:20px}.gold{color:var(--gold2)}.btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;padding:15px 27px;border-radius:999px;font-size:13px;font-weight:700;letter-spacing:.3px;transition:.3s;border:1px solid var(--line)}.btn-gold{background:linear-gradient(135deg,#f3d278,#b77a20);color:#2b0306;border-color:#f3d278;box-shadow:0 12px 35px rgba(215,167,70,.18)}.btn-gold:hover{transform:translateY(-3px);box-shadow:0 17px 45px rgba(215,167,70,.3)}.btn-outline{color:var(--gold2);background:rgba(0,0,0,.14)}.btn-outline:hover{background:rgba(215,167,70,.1);border-color:var(--gold2)}.divider{width:100px;height:1px;background:linear-gradient(90deg,transparent,var(--gold),transparent);margin:25px auto}.ornament{color:var(--gold);font-size:17px;letter-spacing:7px}.spark{position:absolute;width:4px;height:4px;border-radius:50%;background:var(--gold2);box-shadow:0 0 15px var(--gold);opacity:.6}.s1{left:8%;top:25%;animation:float 4s infinite}.s2{left:22%;top:70%;animation:float 5s 1s infinite}.s3{right:10%;top:28%;animation:float 6s .5s infinite}.s4{right:25%;top:68%;animation:float 4.5s 1.5s infinite}@keyframes float{50%{transform:translateY(-14px);opacity:1}}

.nav{position:absolute;top:0;left:0;width:100%;z-index:20;border-bottom:1px solid rgba(255,255,255,.08)}.nav-inner{height:82px;display:flex;align-items:center;justify-content:space-between}.logo{font-size:22px;color:var(--gold2);letter-spacing:2px}.logo small{display:block;font-family:"DM Sans";font-size:7px;letter-spacing:3px;text-align:center;color:#fff;margin-top:3px}.nav-links{display:flex;gap:26px;align-items:center;list-style:none}.nav-links a{font-size:12px;color:#eadfd1;transition:.25s}.nav-links a:hover{color:var(--gold2)}.menu{display:none;color:var(--gold2);font-size:24px}

.hero{min-height:100vh;display:flex;align-items:center;background:linear-gradient(90deg,rgba(27,0,4,.96) 0%,rgba(50,2,7,.75) 43%,rgba(25,0,4,.38) 100%),url("data:image/png;base64,") center/cover no-repeat}.hero:before{content:"";position:absolute;inset:0;background:radial-gradient(circle at 50% 42%,transparent 0 20%,rgba(0,0,0,.25) 65%,rgba(0,0,0,.75) 100%)}.hero-content{position:relative;z-index:2;width:60%;padding-top:80px}.hero-logo{width:min(310px,55vw);margin-bottom:22px;filter:drop-shadow(0 14px 25px rgba(0,0,0,.55))}.hero h1{font-size:clamp(43px,6.3vw,84px);line-height:.98;color:var(--cream);text-shadow:0 8px 25px #000}.hero h1 span{color:var(--gold2);display:block}.hero-sub{font-family:"Playfair Display";font-style:italic;font-size:clamp(18px,2vw,25px);color:#f1d9aa;margin:22px 0;max-width:600px}.hero-meta{display:flex;flex-wrap:wrap;gap:10px;margin:25px 0}.pill{padding:10px 14px;border:1px solid rgba(244,220,147,.35);background:rgba(25,0,4,.55);backdrop-filter:blur(8px);font-size:11px;letter-spacing:1px;color:#f7e7be}.hero-actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:28px}.scroll{position:absolute;bottom:22px;left:50%;transform:translateX(-50%);z-index:3;font-size:9px;letter-spacing:4px;color:#c7b394}

.intro{background:radial-gradient(circle at 50% 0%,rgba(143,17,24,.45),transparent 40%),#260006}.arch{position:absolute;width:530px;height:650px;border:1px solid rgba(215,167,70,.17);border-radius:280px 280px 0 0;left:50%;top:50%;transform:translate(-50%,-48%);pointer-events:none}.arch:before,.arch:after{content:"";position:absolute;border:1px solid rgba(215,167,70,.1);border-radius:250px 250px 0 0}.arch:before{inset:35px}.arch:after{inset:75px}.intro-grid{display:grid;grid-template-columns:1fr 1fr;gap:70px;align-items:center}.intro-card{position:relative;max-width:500px;margin:auto}.intro-card img{width:100%;border:1px solid rgba(215,167,70,.4);box-shadow:0 30px 80px rgba(0,0,0,.45)}.intro-copy{position:relative;z-index:2}.intro-copy h2{margin:13px 0 22px}.intro-copy p{color:var(--muted);line-height:1.95;margin-bottom:18px}.quote{border-left:2px solid var(--gold);padding:8px 0 8px 18px;font-family:"Playfair Display";font-style:italic;color:#f0d49a;font-size:20px;margin:28px 0}

.experience{background:#180003}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.card{min-height:230px;padding:30px 24px;border:1px solid rgba(215,167,70,.16);background:linear-gradient(160deg,rgba(126,11,20,.32),rgba(10,0,2,.4));position:relative;overflow:hidden;transition:.35s}.card:before{content:"";position:absolute;width:120px;height:120px;border:1px solid rgba(215,167,70,.1);border-radius:50%;right:-45px;top:-45px}.card:hover{transform:translateY(-8px);border-color:rgba(215,167,70,.5)}.icon{font-size:30px;margin-bottom:25px}.card h3{color:var(--cream);font-size:21px;margin-bottom:12px}.card p{color:#ad9b88;font-size:13px;line-height:1.8}

.visual{min-height:550px;background:linear-gradient(90deg,rgba(31,0,5,.94),rgba(31,0,5,.25),rgba(31,0,5,.9)),url("https://www.gujaratitrend.com/assets/grand-navratri-night.png") center/cover no-repeat;display:flex;align-items:center}.visual-copy{max-width:650px}.visual-copy h2{font-size:clamp(42px,6vw,76px)}.visual-copy p{color:#e0cdb0;line-height:1.9;margin:22px 0 28px}

.nights{background:#2a0509}.timeline{display:grid;grid-template-columns:repeat(5,1fr);gap:12px}.night{padding:22px 15px;border:1px solid rgba(215,167,70,.16);background:rgba(0,0,0,.18);text-align:center;min-height:145px}.night b{display:block;font-family:Cinzel;color:var(--gold2);font-size:21px;margin:8px 0}.night span{font-size:10px;color:#a9917b;letter-spacing:1.5px;text-transform:uppercase}.night strong{display:block;font-size:12px;color:#f3dfb4;margin-top:10px}.note{text-align:center;color:#9e8977;font-size:11px;margin-top:20px}

.gallery{background:#160002}.gallery-grid{display:grid;grid-template-columns:1.15fr .85fr .85fr;grid-auto-rows:210px;gap:12px}.gitem{position:relative;overflow:hidden;border:1px solid rgba(215,167,70,.15);background:#41070c}.gitem.large{grid-row:span 2}.gitem img{width:100%;height:100%;object-fit:cover;transition:.5s}.gitem:hover img{transform:scale(1.06)}.glabel{position:absolute;left:12px;bottom:12px;padding:7px 10px;background:rgba(20,0,3,.72);font-size:9px;letter-spacing:2px;color:var(--gold2)}

.social{background:radial-gradient(circle at 50% 100%,rgba(140,12,22,.5),transparent 45%),#230005}.social-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.social-card{padding:35px;border:1px solid rgba(215,167,70,.18);background:rgba(0,0,0,.16)}.social-card h3{color:var(--cream);font-size:25px;margin:10px 0}.social-card p{color:#ad9b88;line-height:1.8;font-size:13px;margin-bottom:20px}.social-links{display:flex;gap:10px;flex-wrap:wrap}.social-link{padding:10px 13px;border:1px solid rgba(215,167,70,.3);color:var(--gold2);font-size:11px;border-radius:999px}.social-link:hover{background:rgba(215,167,70,.1)}

.venue{background:linear-gradient(rgba(29,0,4,.88),rgba(29,0,4,.95)),url("https://images.bhaskarassets.com/web2images/960/2022/10/03/karnavati-garba-f_1664799501.jpg") center/cover}.venue-box{max-width:900px;margin:auto;text-align:center;padding:65px 35px;border:1px solid rgba(215,167,70,.35);background:rgba(18,0,3,.62);backdrop-filter:blur(8px)}.venue-box h2{font-size:clamp(34px,5vw,58px)}.venue-details{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;margin:35px 0;background:rgba(215,167,70,.15)}.vd{padding:22px;background:rgba(35,0,5,.88)}.vd small{display:block;color:#9d8775;text-transform:uppercase;letter-spacing:2px;font-size:9px;margin-bottom:7px}.vd strong{color:var(--gold2);font-size:15px}

.cta{padding:125px 0;text-align:center;background:radial-gradient(circle,rgba(140,12,22,.75),transparent 55%),#170002}.cta h2{max-width:900px;margin:auto}.cta p{max-width:650px;margin:20px auto 30px;color:#cbb79d;line-height:1.8}.cta .ornament{margin-bottom:15px}

footer{background:#0d0002;border-top:1px solid rgba(215,167,70,.16);padding:55px 0 25px;text-align:center}.footer-logo{font-family:Cinzel;color:var(--gold2);font-size:24px;letter-spacing:3px}.footer-tag{font-family:"Playfair Display";font-style:italic;color:#8f796b;margin:10px 0 25px}.footer-nav{display:flex;justify-content:center;gap:20px;flex-wrap:wrap;margin-bottom:25px}.footer-nav a{font-size:11px;color:#b6a18c}.copy{font-size:9px;color:#625047;letter-spacing:1px}

@media(max-width:900px){.nav-links{display:none}.menu{display:block}.hero{min-height:850px;background-position:62% center}.hero-content{width:100%;padding-top:120px;text-align:center}.hero-logo{margin:0 auto 20px}.hero-sub{margin-left:auto;margin-right:auto}.hero-meta,.hero-actions{justify-content:center}.intro-grid{grid-template-columns:1fr;gap:45px}.intro-copy{text-align:center}.quote{border-left:0;border-top:1px solid var(--gold);padding:15px 0}.cards{grid-template-columns:1fr 1fr}.timeline{grid-template-columns:repeat(2,1fr)}.social-grid{grid-template-columns:1fr}}
@media(max-width:600px){.section{padding:75px 0}.nav-inner{height:70px}.hero{min-height:820px;background-position:58% center}.hero h1{font-size:47px}.hero-content{padding-top:110px}.hero-logo{width:220px}.cards{grid-template-columns:1fr}.timeline{grid-template-columns:1fr 1fr}.gallery-grid{grid-template-columns:1fr 1fr;grid-auto-rows:155px}.gitem.large{grid-row:span 1}.venue-details{grid-template-columns:1fr}.venue-box{padding:45px 20px}.btn{width:100%}.hero-actions{width:100%}.arch{width:350px;height:480px}}

