.countdown{background:#0d0103;border-top:1px solid rgba(244,210,120,.2);border-bottom:1px solid rgba(244,210,120,.2);padding:24px 0}.count-grid{display:grid;grid-template-columns:1fr 2fr;gap:30px;align-items:center}.count-title{font-family:Cinzel;color:#f5dc93;font-size:14px;letter-spacing:2px}.count-sub{font-size:10px;color:#967d6c;letter-spacing:1.5px;margin-top:6px}.timer{display:grid;grid-template-columns:repeat(4,1fr)}.timer .t{border-left:1px solid rgba(244,210,120,.18);text-align:center}.timer b{display:block;font-family:Cinzel;color:#fff1c7;font-size:28px}.timer span{font-size:8px;color:#947c69;letter-spacing:2px}.qualities{background:#150002}.quality-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.quality{padding:27px 22px;min-height:205px;border:1px solid rgba(244,210,120,.14);background:linear-gradient(145deg,rgba(126,11,20,.3),rgba(0,0,0,.22));position:relative;overflow:hidden;transition:.3s}.quality:hover{transform:translateY(-6px);border-color:rgba(244,210,120,.45)}.quality:after{content:'✦';position:absolute;right:10px;bottom:-25px;font-size:90px;color:rgba(244,210,120,.06)}.quality .qnum{font-size:10px;letter-spacing:2px;color:#d7a746}.quality h3{font-family:'Noto Sans Gujarati',Cinzel;color:#fff3d1;font-size:23px;margin:12px 0 2px}.quality em{font-family:'Playfair Display';color:#f5dc93;font-size:13px}.quality p{font-size:12px;line-height:1.75;color:#aa9581;margin-top:10px}.pass-section{background:#100002}.pass-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.pass-card{position:relative;padding:28px 21px;background:linear-gradient(160deg,#3c050a,#170002);border:1px solid rgba(244,210,120,.2)}.pass-card.pop{border-color:#d7a746;box-shadow:0 15px 45px rgba(215,167,70,.08)}.pass-card .badge{position:absolute;right:0;top:0;background:#d7a746;color:#260004;font-size:8px;padding:7px 10px;font-weight:800}.pass-card h3{font-family:Cinzel;color:#fff3d1;font-size:19px}.pass-price{font-family:Cinzel;color:#f5dc93;font-size:22px;margin:13px 0 2px}.pass-note{font-size:9px;color:#8f7969}.pass-card ul{list-style:none;margin:20px 0}.pass-card li{font-size:11px;color:#bda893;padding:8px 0;border-bottom:1px solid rgba(255,255,255,.06)}.pass-card li:before{content:'✦';color:#d7a746;margin-right:7px}.pass-card .btn{width:100%}.partners{background:#0c0002}.partner-grid{display:flex;flex-wrap:wrap;justify-content:center;gap:10px}.partner-pill{padding:15px 21px;border:1px solid rgba(244,210,120,.13);background:rgba(255,255,255,.02);color:#a99078;font-size:10px;letter-spacing:1px}.nav .nav-links a{font-size:11px}
