/* Premium original-content expansion */
.story-grid,.journey-grid,.values-grid,.faq-grid,.brand-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
.story-card,.journey-card,.value-card,.faq-item,.brand-card{background:linear-gradient(145deg,rgba(255,244,210,.055),rgba(0,0,0,.16));border:1px solid rgba(234,190,85,.18);border-radius:22px;padding:28px;position:relative;overflow:hidden;transition:.3s}
.story-card:hover,.journey-card:hover,.value-card:hover,.faq-item:hover,.brand-card:hover{transform:translateY(-5px);border-color:rgba(234,190,85,.45);box-shadow:0 20px 50px rgba(0,0,0,.18)}
.story-card:before,.journey-card:before,.value-card:before{content:"";position:absolute;inset:auto -25px -35px auto;width:110px;height:110px;border:1px solid rgba(234,190,85,.16);border-radius:50%}
.card-no{font-family:Cinzel,serif;color:var(--gold);font-size:12px;letter-spacing:3px;margin-bottom:18px}.story-card h3,.journey-card h3,.value-card h3,.brand-card h3{font-size:22px;color:var(--cream);margin-bottom:10px}.story-card p,.journey-card p,.value-card p,.faq-item p,.brand-card p{color:var(--muted);line-height:1.75;font-size:14px}
.manifesto{background:radial-gradient(circle at center,rgba(215,167,70,.12),transparent 52%),linear-gradient(180deg,#43070b,#230005);border-top:1px solid var(--line);border-bottom:1px solid var(--line);text-align:center;padding:100px 0}.manifesto h2{max-width:900px;margin:15px auto 20px}.manifesto p{max-width:760px;margin:auto;color:var(--muted);line-height:1.9}
.journey{background:linear-gradient(180deg,rgba(255,255,255,.015),transparent)}
.journey-card{min-height:230px}.journey-icon{font-size:34px;color:var(--gold2);margin-bottom:20px}.journey-card ul{list-style:none;margin-top:16px;display:grid;gap:8px}.journey-card li{font-size:13px;color:#e5d6c0}.journey-card li:before{content:"✦";color:var(--gold);margin-right:8px}
.values{background:#1b0004}.value-card{text-align:center;min-height:190px}.value-symbol{font-size:30px;color:var(--gold2);margin-bottom:14px}
.faq-wrap{max-width:950px;margin:auto;display:grid;gap:12px}.faq-item{padding:24px 26px}.faq-item h3{font-family:"DM Sans";font-size:16px;color:var(--cream);margin-bottom:8px}.faq-item p{font-size:13px}
.brand-grid{grid-template-columns:repeat(2,1fr)}.brand-card strong{display:block;color:var(--gold2);font-family:Cinzel,serif;font-size:18px;margin-bottom:8px}.brand-card span{display:inline-block;margin-top:14px;font-size:11px;letter-spacing:2px;text-transform:uppercase;color:var(--gold)}
.timeline{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin-top:35px}.time-chip{padding:18px 12px;text-align:center;border:1px solid rgba(234,190,85,.2);border-radius:16px;background:rgba(0,0,0,.15)}.time-chip b{display:block;color:var(--gold2);font-family:Cinzel,serif;font-size:20px}.time-chip span{font-size:10px;letter-spacing:1.5px;color:var(--muted);text-transform:uppercase}
.note{margin-top:22px;padding:14px 18px;border-left:2px solid var(--gold);background:rgba(215,167,70,.05);color:#cdbda5;font-size:12px;line-height:1.7}
@media(max-width:800px){.story-grid,.journey-grid,.values-grid,.faq-grid,.brand-grid{grid-template-columns:1fr}.timeline{grid-template-columns:repeat(2,1fr)}.nav-links{display:none}.menu{display:block}}



