.nights{background:radial-gradient(circle at 15% 20%,rgba(142,17,24,.28),transparent 30%),#2a0509}.night,.time-chip{position:relative;overflow:hidden}.night:before,.time-chip:before{content:"";position:absolute;left:50%;top:0;width:70px;height:1px;transform:translateX(-50%);background:linear-gradient(90deg,transparent,var(--gold),transparent)}
.gallery-grid{grid-auto-rows:240px}.gitem{border-radius:16px;box-shadow:var(--shadow)}.gitem:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,transparent 45%,rgba(10,0,2,.7));pointer-events:none}.glabel{z-index:2;border:1px solid rgba(245,220,147,.22);border-radius:999px;backdrop-filter:blur(8px)}
.moments{background:radial-gradient(circle at 50% 0,rgba(142,17,24,.32),transparent 40%),#170003}.moments-grid{display:grid;grid-template-columns:1.35fr .8fr .8fr;grid-template-rows:260px 260px;gap:14px;max-width:1120px;margin:auto}.moment{position:relative;overflow:hidden;border:1px solid rgba(245,220,147,.18);border-radius:20px;background:#280307;box-shadow:var(--shadow);min-height:0}.moment-wide{grid-row:span 2}.moment-tall{grid-column:3;grid-row:span 2}.moment img{width:100%;height:100%;object-fit:cover;transition:transform .7s ease,filter .7s ease;filter:saturate(.9) contrast(1.03)}.moment:hover img{transform:scale(1.07);filter:saturate(1.08) contrast(1.06)}.moment:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,transparent 42%,rgba(12,0,2,.88));pointer-events:none}.moment figcaption{position:absolute;left:22px;right:22px;bottom:20px;z-index:2}.moment figcaption span{display:block;color:var(--gold2);font:11px Cinzel;letter-spacing:3px;margin-bottom:5px}.moment figcaption b{display:block;color:#fff4d2;font:22px Cinzel}.moment figcaption small{display:block;color:#d0bda2;font-size:10px;letter-spacing:1.5px;text-transform:uppercase;margin-top:5px}.image-note{margin:18px auto 0;max-width:900px;text-align:center;color:#8f7969;font-size:10px;letter-spacing:.4px}.image-note span{color:var(--gold);margin-right:7px}
.manifesto{position:relative}.manifesto:before,.manifesto:after{content:"";position:absolute;left:50%;transform:translateX(-50%);border:1px solid rgba(245,220,147,.13);border-radius:50%}.manifesto:before{width:520px;height:520px;top:-210px}.manifesto:after{width:760px;height:760px;top:-330px}.venue-box{border-radius:24px;box-shadow:var(--shadow);position:relative;overflow:hidden}.venue-box:before{content:"✦";position:absolute;right:25px;top:18px;color:rgba(245,220,147,.25);font-size:38px}.partner-pill{border-radius:999px;transition:.3s}.partner-pill:hover{border-color:rgba(245,220,147,.4);color:var(--gold2);transform:translateY(-3px)}.cta{position:relative;overflow:hidden}.cta:before{content:"";position:absolute;left:50%;top:50%;width:600px;height:600px;border:1px solid rgba(245,220,147,.1);border-radius:50%;transform:translate(-50%,-50%)}footer{position:relative}.footer-logo{font-size:28px}
@media(max-width:900px){.hero:after{inset:4% 3%;border-radius:45% 45% 0 0}.moments-grid{grid-template-columns:1fr 1fr;grid-template-rows:260px 260px}.moment-wide{grid-row:span 2}.moment-tall{grid-column:span 1;grid-row:span 2}.hero-content{max-width:100%}}
@media(max-width:600px){.nav-inner{height:72px}.hero{min-height:850px;background-position:60% center}.hero:after{inset:7% 4% 4%}.hero-logo{width:205px}.hero h1{font-size:43px}.hero-sub{font-size:18px}.moments-grid{grid-template-columns:1fr;grid-template-rows:230px 230px 230px 230px}.moment-wide,.moment-tall{grid-row:span 1;grid-column:span 1}.moment figcaption{left:17px;right:17px;bottom:16px}.moment figcaption b{font-size:19px}.gallery-grid{grid-auto-rows:190px}.section-head{margin-bottom:38px}.manifesto{padding:85px 0;overflow:hidden}.manifesto:before{width:360px;height:360px}.manifesto:after{width:500px;height:500px}}

/* SHAKTI CHAKRA PREMIUM EVENT SYSTEM */
:root{--sc-gold:#d7a746;--sc-gold2:#f5dc93;--sc-muted:#d0c0a7;--sc-line:rgba(215,167,70,.28)}
body{background:radial-gradient(circle at 50% 0%,#4a070c 0,#210105 38%,#0f0103 100%);color:#fff5dc}
.nav{backdrop-filter:blur(18px);background:rgba(17,1,4,.88)!important;border-bottom:1px solid var(--sc-line);position:fixed;top:0;z-index:1000;width:100%}
.nav-links a{font-family:'DM Sans',sans-serif;font-size:12px;letter-spacing:.16em;text-transform:uppercase;font-weight:700}.nav-links a:hover{color:var(--sc-gold2)}
.hero-signature{display:inline-flex;margin-top:24px;padding:12px 18px;border:1px solid rgba(245,220,147,.45);border-radius:999px;background:rgba(0,0,0,.24);color:var(--sc-gold2);font-size:11px;font-weight:800;letter-spacing:.16em}
.sc-section{position:relative;padding:110px 0;border-top:1px solid var(--sc-line);overflow:hidden}.sc-section:before{content:'✦';position:absolute;right:7%;top:55px;color:rgba(215,167,70,.25);font-size:70px}.eyebrow{color:var(--sc-gold2);font-size:11px;letter-spacing:.28em;font-weight:800;margin-bottom:18px}.sc-section h2{font-family:Cinzel,serif;font-size:clamp(38px,6vw,78px);line-height:.98;letter-spacing:.02em;margin-bottom:25px}.sc-section h2 em{font-family:'Playfair Display',serif;font-weight:500;color:var(--sc-gold2)}.sc-section p{color:var(--sc-muted);line-height:1.8}.lead{font-size:19px;line-height:1.7!important;color:#f5e8cb!important}.narrow{max-width:760px}.record-grid,.split{display:grid;grid-template-columns:1fr 1fr;gap:60px;align-items:center}.record-grid img,.split img{width:100%;aspect-ratio:16/10;object-fit:cover;border:1px solid var(--sc-line);border-radius:4px;box-shadow:0 25px 70px rgba(0,0,0,.35)}.record-stats{display:flex;gap:12px;margin-top:35px}.record-stats span{flex:1;padding:22px 15px;border:1px solid var(--sc-line);background:linear-gradient(145deg,rgba(215,167,70,.1),rgba(255,255,255,.02));text-align:center}.record-stats b{display:block;font:700 34px Cinzel;color:var(--sc-gold2)}.record-stats small{font-size:9px;letter-spacing:.14em;color:var(--sc-muted)}.feature-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:45px}.feature-grid article,.impact-grid div{padding:24px;border:1px solid var(--sc-line);background:rgba(255,255,255,.025);font-family:Cinzel,serif;letter-spacing:.04em;transition:.3s}.feature-grid article:hover,.impact-grid div:hover{transform:translateY(-4px);border-color:var(--sc-gold);background:rgba(215,167,70,.07)}.check-list{display:grid;grid-template-columns:1fr 1fr;gap:14px 28px;margin:25px 0;list-style:none;color:var(--sc-muted)}.check-list li:before{content:'✦';color:var(--sc-gold);margin-right:10px}.timeline{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:45px}.timeline>div{padding:32px;border:1px solid var(--sc-line);min-height:220px;background:linear-gradient(145deg,rgba(215,167,70,.07),rgba(255,255,255,.02))}.timeline span{color:var(--sc-gold);font:700 32px Cinzel}.timeline h3{margin:20px 0 12px;font:700 20px Cinzel}.viral-list p{padding:13px 0;border-bottom:1px solid rgba(215,167,70,.15)}.viral-list b{display:inline-block;color:var(--sc-gold2);width:42px}.impact-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin-top:45px}.impact-grid div{text-align:center;min-height:125px;display:flex;align-items:center;justify-content:center}.artist-card{display:grid;grid-template-columns:1fr 1fr;border:1px solid var(--sc-line);background:rgba(255,255,255,.025);margin-top:45px}.artist-card img{width:100%;height:100%;min-height:340px;object-fit:cover}.artist-card>div{padding:55px;display:flex;flex-direction:column;justify-content:center}.artist-card span{font-size:10px;letter-spacing:.2em;color:var(--sc-gold)}.artist-card h3{font:700 32px Cinzel;margin:15px 0}.sponsor-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:45px}.sponsor-grid article{padding:34px;border:1px solid var(--sc-line);background:linear-gradient(150deg,rgba(215,167,70,.08),rgba(255,255,255,.025));min-height:300px}.sponsor-grid b{display:block;font:700 21px Cinzel;color:var(--sc-gold2);margin-bottom:14px}.sponsor-grid strong{display:block;color:#fff;font-size:24px;margin-bottom:20px}.category-strip{margin-top:22px;padding:22px;border:1px solid var(--sc-line);color:var(--sc-muted);line-height:2;letter-spacing:.04em}.btn-gold{box-shadow:0 8px 30px rgba(215,167,70,.18);transition:.3s}.btn-gold:hover{transform:translateY(-2px);box-shadow:0 12px 35px rgba(215,167,70,.3)}
@media(max-width:900px){.record-grid,.split,.artist-card{grid-template-columns:1fr}.feature-grid,.timeline,.sponsor-grid{grid-template-columns:1fr 1fr}.impact-grid{grid-template-columns:1fr 1fr}.check-list{grid-template-columns:1fr}.sc-section{padding:80px 0}}
@media(max-width:600px){.feature-grid,.timeline,.sponsor-grid,.impact-grid{grid-template-columns:1fr}.record-stats{flex-direction:column}.hero-signature{font-size:8px;letter-spacing:.1em}.sc-section h2{font-size:42px}.artist-card>div{padding:30px}.nav-links{display:none}}
